export function initialLanguage(search=location.search){const query=new URLSearchParams(search).get('lang');if(['en','es'].includes(query))return query;try{const saved=localStorage.getItem('mecanica.locale.v1');if(['en','es'].includes(saved))return saved;}catch{}return navigator.language?.startsWith('es')?'es':'en';}
